"""Undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.context import Context
from binkeep.errors import DataError, Refused

DEFAULT_HISTORY = 20


def is_format2(e: dict) -> bool:
    return e.get("v") == 2


class Stacks:
    """The *done* and *undone* stacks, read from the journal (undo.md, section 2)."""

    def __init__(self):
        self.done: list[dict] = []
        self.undone: list[dict] = []
        self.dropped: set[int] = set()  # seqs of dropped operations
        self.undo_line: dict[int, dict] = {}  # target seq -> latest undo line

    def feed(self, e: dict) -> None:
        op = e["op"]
        if op in journal.OPS:
            self.dropped.update(o["seq"] for o in self.undone)
            self.undone.clear()
            self.done.append(e)
        elif op == "undo":
            target = e.get("target")
            if not self.done or not _same(self.done[-1], target):
                raise DataError("journal", f"#{e['seq']}: undo does not match the top of done")
            self.undone.append(self.done.pop())
            self.undo_line[self.undone[-1]["seq"]] = e
        elif op == "redo":
            target = e.get("target")
            if not self.undone or not _same(self.undone[-1], target):
                raise DataError("journal", f"#{e['seq']}: redo does not match the top of undone")
            self.done.append(self.undone.pop())


def _same(op: dict, target) -> bool:
    return isinstance(target, int) and not isinstance(target, bool) and op["seq"] == target


def replay(entries: list[dict]) -> Stacks:
    s = Stacks()
    for e in entries:
        s.feed(e)
    return s


def _effects(e: dict) -> list:
    effects = e.get("effects")
    if not isinstance(effects, list):
        raise DataError("journal", f"#{e['seq']}: no effects")
    return effects


def _plan_undo(ctx: Context, op: dict) -> list[tuple[str, int]]:
    """The (bin, quantity to set) changes that reverse an operation, in order.

    Format 1 changes depend on the stock at the time, so they are given as
    deltas by `_apply`; here every change is (bin, ("set", qty) | ("add", delta)).
    """
    raise NotImplementedError


def _changes_undo(ctx: Context, op: dict) -> list[tuple[str, str, int]]:
    """Changes ("set"|"add", bin, number) that take an operation back, in order."""
    kind = op["op"]
    if is_format2(op):
        return [("set", normalize(str(x["bin"])), x["before"]) for x in reversed(_effects(op))]
    try:
        if kind == "count":
            raise Refused("irreversible", f"#{op['seq']}: the quantity before the count is not known")
        if kind == "receive":
            qty = op["qty"]
            if op.get("uom") == "pk":
                item = ctx.items.get(op["sku"])
                if item is None:
                    raise Refused("unknown-sku", f"no item {op['sku']}")
                qty *= item.pack_size
            return [("add", normalize(op["bin"]), -qty)]
        if kind == "issue":
            return [("add", normalize(b), q) for b, q in reversed(op["picks"])]
        if kind == "move":
            return [("add", normalize(op["to"]), -op["qty"]), ("add", normalize(op["from"]), op["qty"])]
    except (KeyError, TypeError, ValueError):
        raise DataError("journal", f"#{op['seq']}: malformed line") from None
    raise DataError("journal", f"#{op['seq']}: unexpected op {kind}")


def _changes_redo(ctx: Context, undo_line: dict) -> list[tuple[str, str, int]]:
    return [("set", normalize(str(x["bin"])), x["before"]) for x in reversed(_effects(undo_line))]


def _apply(ctx: Context, store, sku: str, changes) -> list[dict]:
    for _, code, _n in changes:
        if code not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {code}")
    effects = []
    for how, code, n in changes:
        before = store.qty(sku, code)
        after = n if how == "set" else before + n
        store.set(sku, code, after, restore=True)
        effects.append({"bin": code, "before": before, "after": after})
    return effects


def steps(ctx: Context, kind: str, n: int):
    """Carries out n undo or redo steps in memory; returns (store, new entries, targets)."""
    stacks = replay(ctx.entries)
    store = ctx.store.copy()
    seq = journal.next_seq(ctx.entries)
    new, targets = [], []
    for _ in range(n):
        if kind == "undo":
            if not stacks.done:
                raise Refused("nothing-to-undo", "nothing to undo")
            op = stacks.done[-1]
            if op["op"] == "fix":
                raise Refused("barrier", f"#{op['seq']} is a fix")
            changes = _changes_undo(ctx, op)
        else:
            if not stacks.undone:
                raise Refused("nothing-to-redo", "nothing to redo")
            op = stacks.undone[-1]
            line = stacks.undo_line.get(op["seq"])
            if line is None:
                raise DataError("journal", f"#{op['seq']}: no undo line")
            changes = _changes_redo(ctx, line)
        effects = _apply(ctx, store, op["sku"], changes)
        e = journal.entry(seq, kind, ctx.by, op["sku"], target=op["seq"], effects=effects)
        seq += 1
        stacks.feed(e)
        new.append(e)
        targets.append(op)
    return store, new, targets


def status_lines(ctx: Context, limit: int) -> list[str]:
    stacks = replay(ctx.entries)
    on_done = {o["seq"] for o in stacks.done}
    on_undone = {o["seq"] for o in stacks.undone}
    ops = [e for e in ctx.entries if e["op"] in journal.OPS]
    lines = []
    for e in reversed(ops[-limit:]):
        if e["seq"] in on_done:
            status = "barrier" if e["op"] == "fix" else "done"
        elif e["seq"] in on_undone:
            status = "undone"
        else:
            status = "dropped"
        lines.append(f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {status}")
    return lines

