    def run(ctx, a):
        store, new, targets = undo.steps(ctx, kind, a.steps)
        ctx.commit(store, new)
        lines = []
        for e, op in zip(new, targets):
            lines.append(f"#{e['seq']} {e['op']} {e['sku']} (#{op['seq']} {op['op']})")
            lines.extend(f"  {x['bin']} {x['before']} -> {x['after']}" for x in e["effects"])
        return lines

    return run


